import { AbsoluteFill, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import React, { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface DriftProps {
  children: React.ReactNode;
  grow?: number;
}

function DriftBase({ children, grow = 0.035 }: DriftProps) {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const scale = interpolate(frame, [0, durationInFrames], [1, 1 + grow]);
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  grow: {
    type: "number",
    min: -0.1,
    max: 0.15,
    step: 0.005,
    default: 0.035,
    description: "Grow",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["grow","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  grow: 0.035,
  speed: 1,
};

type DriftElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof DriftBase>;

const DriftInner = forwardRef<
  HTMLDivElement,
  DriftElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Drift>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <DriftBase
          {...(componentProps as unknown as ComponentProps<typeof DriftBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Drift = Interactive.withSchema({
  Component: DriftInner,
  componentName: "<Drift>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
